<?php require 'config.php';$count=(int)$pdo->query("SELECT COUNT(*) FROM users WHERE role='admin'")->fetchColumn();$msg='';
if($_SERVER['REQUEST_METHOD']==='POST'&&$count===0){verify_csrf();$n=trim($_POST['username']??'');$p=$_POST['password']??'';if(strlen($n)<3||strlen($p)<8)$msg='Username must be 3+ characters and password 8+ characters.';else{$s=$pdo->prepare("INSERT INTO users(username,password,status,role) VALUES(?,?,'approved','admin')");$s->execute([$n,password_hash($p,PASSWORD_DEFAULT)]);$msg='Admin created. Delete setup_admin.php now.';$count=1;}}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Initial Admin Setup</title><link rel="stylesheet" href="assets/style.css"></head><body class="auth"><main class="card"><h1>Initial admin setup</h1><?php if($count):?><p>An admin account exists. Delete setup_admin.php for security.</p><?php else:?><?php if($msg):?><div class="alert"><?=$msg?></div><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><label>Admin username</label><input name="username" required><label>Password (8+ characters)</label><input type="password" name="password" minlength="8" required><button>Create admin</button></form><?php endif;?></main></body></html>